SZGame2D.onStart(function __szProjectRun() {
  const __szProjectRunContext = window.__SZProjectLifecycle.begin(() => SZGame2D.restart());
  // Ao iniciar
  SZGame2D.setupStage(640, 480, "#dcebf7");
  SZGame2D.enableClassicControls("always");
  let noChao = 1;
  let pulos = 0;
  const pinguim = SZGame2D.createSprite({ x: 280, y: 300, w: 44, h: 48, image: "pinguim" });
  const chao = SZGame2D.createSprite({ x: 120, y: 348, w: 400, h: 40, image: "gelo" });
  // Quando acontecer
  SZGame2D.onKey("Enter", () => {

  }, "pico-quadro-1_events_0");
  SZGame2D.onKey("Space", () => {

  }, "pico-quadro-1_events_1");
  // Enquanto estiver rodando
  // O jogo roda 60 passos por segundo: cada volta desenha um "quadro" do filme.
  SZGame2D.gameLoop(function update() {
    SZGame2D.applyGravity(pinguim);
    SZGame2D.applyVelocity(pinguim);
    if (SZGame2D.spriteY(pinguim) > 299) {
      pinguim.vx = 0; pinguim.vy = 300 - SZGame2D.spriteY(pinguim);
      SZGame2D.applyVelocity(pinguim);
      pinguim.vx = 0; pinguim.vy = 0;
      noChao = 1;
    }
    SZGame2D.clear();
    SZGame2D.drawBackdrop(ctx, "pico");
    SZGame2D.drawLabel(ctx, "Pulo com apoio", 24, 35, "#173956", 19, "left");
    SZGame2D.drawLabel(ctx, "Espaço pula quando o pinguim está no chão.", 24, 72, "#173956", 19, "left");
    SZGame2D.drawLabel(ctx, "No ar, espere o próximo pouso.", 24, 103, "#173956", 19, "left");
    SZGame2D.drawSprite(ctx, pinguim);
    SZGame2D.drawSprite(ctx, chao);
    SZGame2D.drawLabel(ctx, "Pulos:", 24, 420, "#173956", 19, "left");
    SZGame2D.drawLabel(ctx, pulos, 320, 420, "#173956", 19, "left");
    SZGame2D.drawLabel(ctx, "Enter: nova rodada depois de completar o extra.", 24, 445, "#173956", 19, "left");
  }, "pico-quadro-1_loops_0");
}, "__sz-project");

