SZGame2D.onStart(function __szProjectRun() {
  const __szProjectRunContext = window.__SZProjectLifecycle.begin(() => SZGame2D.restart());
  // Ao iniciar
  SZGame2D.setupStage(640, 480, "#dcebf7");
  SZGame2D.enableClassicControls("always");
  let faltam = 120;
  let atravessou = 0;
  let passagens = 0;
  const pinguim = SZGame2D.createSprite({ x: 160, y: 260, w: 44, h: 48, image: "pinguim" });
  const barreira = SZGame2D.createSprite({ x: 320, y: 240, w: 60, h: 100, image: "gelo" });
  const bandeira = SZGame2D.createSprite({ x: 500, y: 228, w: 40, h: 80, image: "bandeira" });
  // Quando acontecer
  SZGame2D.onKey("Enter", () => {

  }, "pico-quadro-5_events_0");
  SZGame2D.onKey("Space", () => {

  }, "pico-quadro-5_events_1");
  // Enquanto estiver rodando
  // O jogo roda 60 passos por segundo: cada volta desenha um "quadro" do filme.
  SZGame2D.gameLoop(function update() {
    if (faltam > 0) {
      faltam = faltam - 1;
    }
    if (atravessou === 1) {
      if (SZGame2D.spriteX(pinguim) < 500) {
        pinguim.vx = 2; pinguim.vy = 0;
        SZGame2D.applyVelocity(pinguim);
