    SZGame2D.drawLabel(ctx, "A neve está cedendo. Espere o contador zerar.", 24, 72, "#173956", 19, "left");
    SZGame2D.drawLabel(ctx, "Espaço atravessa a passagem uma vez.", 24, 103, "#173956", 19, "left");
    SZGame2D.drawSprite(ctx, pinguim);
    if (faltam > 0) {
      SZGame2D.drawSprite(ctx, barreira);
    }
    SZGame2D.drawSprite(ctx, bandeira);
    SZGame2D.drawLabel(ctx, "Neve cedendo:", 24, 380, "#173956", 19, "left");
    SZGame2D.drawLabel(ctx, faltam, 320, 380, "#173956", 19, "left");
    SZGame2D.drawLabel(ctx, "Passagens:", 24, 420, "#173956", 19, "left");
    SZGame2D.drawLabel(ctx, passagens, 320, 420, "#173956", 19, "left");
